        samples.append((pid, seq, i, t0, seq[i+15]['core_temp'], first_dec))
people=sorted(set(s[0] for s in samples))

def run_filter(hist, a0, bhr, bsk, bw, alpha, hr_miss, init=37.0, mode='prop', bwk=0.0):
    estimate=init
    previous=estimate
    last_hr=hr_miss
    for row in hist:
        previous=estimate
        if row['hr'] is not None:
            last_hr=row['hr']
            hr=row['hr']
        else:
            hr=last_hr
        skin = row['skin_temp'] if row['skin_temp'] is not None else 34
        watts = row['watts'] if row['watts'] is not None else 0
        mass = row['mass'] if row.get('mass') else 70
        target = a0 + bhr*(hr-70) + bsk*(skin-33) + bw*watts + bwk*(watts/mass)
        estimate += alpha*(target-estimate)
    last=hist[-1]
    hr = last['hr'] if last['hr'] is not None else last_hr
    skin = last['skin_temp'] if last['skin_temp'] is not None else 34
    watts = last['watts'] if last['watts'] is not None else 0
    mass = last['mass'] if last.get('mass') else 70
    target = a0 + bhr*(hr-70) + bsk*(skin-33) + bw*watts + bwk*(watts/mass)
    if mode=='now':
        return estimate, target, previous
    if mode=='lin':
        return estimate + 15*max(-0.03, min(0.03, estimate-previous)), target, previous
    if mode=='prop':
        for _ in range(15):
            estimate += alpha*(target-estimate)
        return estimate, target, previous
    return estimate, target, previous

