train=json.load(open('train.json'))

samples=[]
for pid, seq in train.items():
    t0=seq[0]['time_min']
    watts=[r['watts'] for r in seq]
    first_dec=None
    for i,w in enumerate(watts):
        if w < watts[0]-1e-9:
            first_dec=i; break
    if first_dec is None: continue
    for i in range(first_dec, len(seq)-15):
        if seq[i+15]['core_temp'] is None: continue
        samples.append((pid, seq, i, t0, seq[i+15]['core_temp'], first_dec, seq[i]['time_min']-t0))
people=sorted(set(s[0] for s in samples))

# Heat balance Euler
# T += k_w * watts/mass + k_s * (skin - T) + k0
# k_s > 0 means T pulled toward skin (wrong direction if skin < T... actually heat loss ~ (T-skin) so T += -k_s*(T-skin) = k_s*(skin-T))

def simulate(hist, kw, ks, k0, init, n_future=15):
    T=init
    for row in hist:
        w=row['watts'] if row['watts'] is not None else 0
        skin=row['skin_temp'] if row['skin_temp'] is not None else 34
        mass=row['mass'] if row.get('mass') else 70
        T += kw*(w/mass) + ks*(skin-T) + k0
        T=min(41, max(35.5, T))
    last=hist[-1]
    w=last['watts'] if last['watts'] is not None else 0
    skin=last['skin_temp'] if last['skin_temp'] is not None else 34
    mass=last['mass'] if last.get('mass') else 70
    for _ in range(n_future):
        T += kw*(w/mass) + ks*(skin-T) + k0
        T=min(41, max(35.5, T))
    return T

def eval(kw, ks, k0, init):
    pmaes={}
    for hold in people:
        errs=[]
        for pid, seq, i, t0, y, fd, el in samples:
            if pid!=hold: continue
            yhat=simulate(seq[:i+1], kw, ks, k0, init)
            errs.append(abs(yhat-y))
        pmaes[hold]=float(np.mean(errs))
    return float(np.mean(list(pmaes.values()))), pmaes

best=999; bk=None
for kw in [0.005, 0.01, 0.015, 0.02, 0.03]:
  for ks in [0.0, 0.01, 0.02, 0.04, 0.08]:
    for k0 in [-0.02, -0.01, 0.0, 0.01, 0.02]:
      for init in [37.0, 37.2, 37.4]:
        mu,_=eval(kw,ks,k0,init)
        if mu<best:
          best=mu; bk=(mu,kw,ks,k0,init)
print('best heatbal', bk)
