open('submission.py','w').write(r'''"""3A core-temp +15 min: saturating time-mass curve blended with ECTemp-style filter."""
import math


def _carry(hist):
    last_hr = None
    rows = []
    for r in hist:
        d = r
        hr = d.get("hr")
        if hr is not None:
            last_hr = hr
        rows.append((d, last_hr))
    return rows


def _elapsed(hist):
    t0 = hist[0].get("time_min")
    t1 = hist[-1].get("time_min")
    if t0 is not None and t1 is not None:
        el = t1 - t0
        if el < 0:
            el = 0.0
        # if sampling is ~1 min, len-1 is a fallback when clocks are odd
        n = len(hist) - 1
        if n >= 0 and (el > n * 4 + 5 or (n >= 5 and el * 4 < n)):
            el = float(n)
        return float(el)
    return float(max(0, len(hist) - 1))


def _time_curve(elapsed, mass, horizon):
    # Fit on train minutes: T ~= 37.50 + 1.666*(1-exp(-t/15)) - 0.00647*mass
    tau = 15.0
    t = max(0.0, elapsed + horizon)
    return 37.5006 + 1.6664 * (1.0 - math.exp(-t / tau)) - 0.006474 * mass


def _filter_forecast(hist, horizon, init=37.18):
    """Exponential smoother toward an HR/watts target; freeze last sensors for forecast."""
    a0 = 37.35
    bhr = 0.010
    bw = 0.0009
    alpha = 0.11
    hr_miss = 155.0
    est = init
    last_hr = hr_miss
    last_skin = 34.0
    last_w = 0.0
    for r in hist:
        if r.get("hr") is not None:
            last_hr = r["hr"]
        if r.get("skin_temp") is not None:
            last_skin = r["skin_temp"]
        if r.get("watts") is not None:
            last_w = r["watts"]
        target = a0 + bhr * (last_hr - 70.0) + bw * last_w
        est += alpha * (target - est)
    target = a0 + bhr * (last_hr - 70.0) + bw * last_w
    steps = int(round(horizon)) if horizon else 0
    if steps < 0:
        steps = 0
    decay = 1.0 - (1.0 - alpha) ** steps if steps else 0.0
    est = est + decay * (target - est)
    return est


def predict(request):
    hist = request.get("history") or []
    task = request.get("task") or "3A"
    horizon = request.get("horizon_min")
    if horizon is None:
        horizon = 15.0 if task == "3A" else 0.0
    horizon = float(horizon)

    if not hist:
        mu = 37.4 if horizon else 37.2
        return {"mean": mu, "lower": mu - 1.0, "upper": mu + 1.0}

    last = hist[-1]
    mass = last.get("mass")
    if mass is None or mass <= 0:
        mass = 73.0
    mass = float(mass)

    elapsed = _elapsed(hist)
    mu_time = _time_curve(elapsed, mass, horizon)
    mu_filt = _filter_forecast(hist, horizon)

    has_hr = any(r.get("hr") is not None for r in hist)
    n = len(hist)
    if has_hr:
        w_time = 0.55
    else:
        w_time = 0.80
    mu = w_time * mu_time + (1.0 - w_time) * mu_filt

    # mild remaining-rise cut when watts already reduced a lot (3A after first drop)
    if horizon > 0 and n >= 2:
        w0 = hist[0].get("watts")
        w1 = last.get("watts")
        if w0 and w1 is not None and w0 > 1:
            wfrac = max(0.4, min(1.0, w1 / w0))
            # do not apply a large correction; only shrink a slice of future rise
            cur = _time_curve(elapsed, mass, 0.0)
            rise = mu - cur
            if rise > 0:
                mu = cur + rise * (0.72 + 0.28 * wfrac)

    if mu < 36.4:
        mu = 36.4
    elif mu > 40.2:
        mu = 40.2

    half = 0.90
    if not has_hr:
        half += 0.20
    if elapsed < 8:
        half += 0.15
    if n < 6:
        half += 0.10
    half = min(2.4, max(0.4, half))
    return {"mean": float(mu), "lower": float(mu - half), "upper": float(mu + half)}
''')
